댓글 0 글자크기 설정 가 가 기사의 본문 내용은 이 글자크기로 변경됩니다. $(function() { // information group $(".info-group").on("click", ".info-update", function(e) { const _this = $(e.currentTarget); if(_this.hasClass("show")) { _this.removeClass("show"); } else { _this.addClass("show"); } }); // scrap button $('.helper-tool-group').on('click', '.page-scrap', function(e) { var idxno = $(this).data('idxno'); if(confirm("기사를 스크랩 하시겠습니까?")){ $.ajax({ type: 'post', dataType: 'json', url: '/news/articleScrap.ajax.php', data: {'tp':'A', 'idxno':idxno}, success: function(data) { alert(data[1]); }, error: function(error, request) { alert('error!!!'); console.log("code:"+request.status+"\n"+"message:"+request.responseText+"\n"+"error:"+error); } }); } }); }); 이 기사를 공유합니다 2026-04-18 17:05:56(광주=뉴스1) 서충섭 기자 = 더불어민주당 전남광주특별시장 후보인 민형배 의원(광주 광산을)이 18일 자정 국회에서 정치개혁법안을 처리를 앞두고 윤종오 진보당 의원과 사진을 찍고 있다.(민형배 SNS. 재배포 및 DB 금지) 더불어민주당 전남광주특별시장 후보인 민형배 국회의원(광주 광산을)이 국회의 정치개혁법안 통과로 광주 광역의원 정수가 4명 늘어나는 데 그친데 대해 "찬성하기 어렵다"고 아쉬움을 토로했다.민 의원은 18일 자정께 페이스북을 통해 "정치개혁법안 처리가 시간에 쫓긴 졸속입법이라는 소수정당 의원들이 비판이 이어지고 있다"며 "무엇보다 전남광주통합특별시 광역의원 지역구 정수 조정이 4개 선거구 4명에 그쳐 통합에 따른 현저한 불균형이 해소되지 않았다. 찬성하기 어렵다"고 밝혔다.민 의원은 "정치개혁 실패를 매번 반복한다. 아프다"며 "온전한 정치개혁의 길로 나아가지 못해 촛불시민께 송구할 따름이다"고 전했다.곧이어 광주에서 최초로 4개 광역의원 선거구에 중대선거구제를 도입하고 전남광주의 비례대표 비율을 4% 늘리는 정치개혁법안이 통과되자 민 의원은 재차 "전반적으로 불완전하지만 진전도 꽤 있다"고 평가했다.중대선거구제는 기존 선거구를 통폐합해 정당 득표순으로 후보를 선출하는 제도로 민주당 득표율이 저조할 경우 야당 후보가 당선될 가능성이 열렸다.민 의원은 "양당 독점 정치를 조금이나마 흔들고 정치적 다양성과 대표성을 넓히는 개혁의 첫걸음을 광주가 냈다는 점이 반갑다"며 "정치개혁의 본질은 사표를 줄이고 민심을 의석에 더 정확하게 반영, 더 다양한 정치세력이 시민의 선택을 받게 하는 것이다. 그래야 덜 폐쇄되고, 덜 독점되며 시민의 삶을 대변할 수 있다"고 강조했다.그러면서 "저도 구청장에서 국회의원까지 풀뿌리 현장에서 정치를 시작했기에 오늘의 변화로는 만족할 수 없다. 이보다 더 담대한 개혁이 필요하다"면서 "양당제는 안정성과 효율성은 분명하나, 특정 정당 지지세가 압도적이면 경쟁은 줄고 민의의 통로가 좁아진다. 지역 정치 안에서 다양한 정치세력이 건강하게 견제할 때 자치는 투명해지고 진보한다"고 덧붙였다.현재 광주와 전남의 지역구 광역의원 수 차이가 22명 대 61명으로 세 배 차이가 나는 가운데 전남광주행정통합으로 대표성 논란이 제기되고 있지만 지역구 민심 등을 고려한 민주당 전남 국회의원들의 반대 등으로 전남이 줄어드는 대신 광주가 소폭 증가하는 합의안이 마련됐다. #AD174493715234.ad-template { margin:auto; positio